// CONCEPT 3: SMART LOAD BALANCER & DYNAMIC ROUTER
const item = ($input.first() && $input.first().json) ? $input.first().json : {};
const prompt = item.chatInput || item.message || item.prompt || 'Analyze database query performance and write 50 lines of complex SQL code';

let routedProvider = 'azure-openai-primary';
let routedModel = 'gpt-4o-mini';
let routingReason = 'Cost-Optimized Fast Track';

if (prompt.length > 200 || prompt.toLowerCase().includes('sql') || prompt.toLowerCase().includes('analyze') || prompt.toLowerCase().includes('code')) {
  routedProvider = 'azure-openai-primary';
  routedModel = 'gpt-4o';
  routingReason = 'High-Complexity Technical Query';
} else if (prompt.length < 30) {
  routedProvider = 'huggingface-local';
  routedModel = 'Qwen2.5-0.5B-Instruct';
  routingReason = 'Local Lightweight Model Fast-Track';
}

return {
  json: {
    output: `🔀 [ROUTER DECISION]\nPrompt: "${prompt}"\nModel Selected: ${routedModel} (${routedProvider})\nReason: ${routingReason}`,
    routedModel,
    routedProvider,
    routingReason
  }
};
